#!/usr/bin/env python3
"""Drive a program under a PTY, send input lines, capture all output bytes."""
import os, pty, sys, time, select, errno

def run(argv, inputs, settle=0.4, total_timeout=8.0):
    pid, fd = pty.fork()
    if pid == 0:
        os.execv(argv[0], argv)
    out = b""
    start = time.time()
    idx = 0
    last = time.time()
    while True:
        if time.time() - start > total_timeout:
            break
        r, _, _ = select.select([fd], [], [], 0.05)
        if r:
            try:
                data = os.read(fd, 65536)
            except OSError as e:
                if e.errno == errno.EIO:
                    break
                raise
            if not data:
                break
            out += data
            last = time.time()
        else:
            if idx < len(inputs) and time.time() - last > settle:
                os.write(fd, inputs[idx])
                idx += 1
                last = time.time()
            elif idx >= len(inputs) and time.time() - last > settle:
                # check if child exited
                done, status = os.waitpid(pid, os.WNOHANG)
                if done:
                    # drain
                    try:
                        while True:
                            data = os.read(fd, 65536)
                            if not data:
                                break
                            out += data
                    except OSError:
                        pass
                    rc = os.waitstatus_to_exitcode(status)
                    return out, rc
                break
    try:
        os.kill(pid, 9)
    except ProcessLookupError:
        pass
    try:
        _, status = os.waitpid(pid, 0)
        rc = os.waitstatus_to_exitcode(status)
    except ChildProcessError:
        rc = None
    return out, rc

if __name__ == "__main__":
    import json
    spec = json.loads(sys.argv[1])
    argv = spec["argv"]
    inputs = [s.encode() for s in spec.get("inputs", [])]
    out, rc = run(argv, inputs, spec.get("settle", 0.4), spec.get("timeout", 8.0))
    sys.stdout.write("RC=%r\n" % rc)
    sys.stdout.write(repr(out))
    sys.stdout.write("\n")

